import numpy as np
from scipy.optimize import least_squares
t=df['t'].values; x=df['x'].values; v=df['v'].values; y=df['dv_dt'].values
Vn=np.var(y); S=np.sqrt(v)
def run(F,label):
    best=(np.inf,None)
    for a0 in [0.5,1.1,2.0]:
     for b0 in [3.4,-3.4,1.0]:
      for c0 in [0.1,0.4,1.0,2.0,3.0]:
        def resf(p):
            B=np.column_stack([v**2, np.log(1+p[0]*x)*t, np.sin(p[1]*S), F(p[2]), np.ones_like(t)])
            c=np.linalg.lstsq(B,y,rcond=None)[0]
            return np.nan_to_num(y-B@c,nan=1e3,posinf=1e3,neginf=-1e3)
        try:
            s=least_squares(resf,[a0,b0,c0],bounds=([1e-3,-20,-10],[50,20,10]),max_nfev=100)
            n=np.mean(s.fun**2)/Vn
            if n<best[0]: best=(n,s.x)
        except Exception: pass
    print(label, best[0], np.round(best[1],4))
